insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('DJ', 'default', 'Plan de référence des entreprises commerciales (regroupement propre au pack, par les lignes du bilan et du compte de résultat)', '{}'::jsonb, true, 'companies', array['DJ-BS', 'DJ-IS']::text[], null, 'Le Code général des impôts 2016 (articles 210 et 211) exige des documents comptables et des pièces originales présentables à l''administration, sans décrire un plan de comptes. Aucun plan comptable national n''a pu être lu en source ouverte. Les classes (1 actif circulant, 2 actif immobilisé, 3 dettes à court terme, 4 dettes à long terme, 5 capitaux propres, 6 produits, 7 à 9 charges) et tous les codes sont le regroupement de ce pack d''après les postes d''un bilan et d''un compte de résultat. Un comptable djiboutien doit le comparer à la pratique locale avant qu''une société y tienne ses livres. Voir README.md.', 'cgi')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

