insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('DJ', 'DJ-P-10', 'TVA 10 % — achat déductible', '{}'::jsonb, null, 'percent', 10, 'purchase', 'domestic', date '2015-01-01', null, 'Code général des impôts 2016, articles 188 et 189 : la TVA qui a grevé les éléments du prix d''une opération imposable est déductible le même mois, sur facture d''un fournisseur autorisé à la mentionner ou sur document douanier portant le NIF de l''entreprise ; elle doit être nécessaire à l''exploitation. Les lignes 13 et 14 du formulaire (importations, achats locaux) et 11 et 12 (investissements) ne sont pas distinguées : une seule case INPUT.', null, null, 200, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('DJ', 'DJ-P-10-NODEDUCT', 'TVA 10 % — achat dont la taxe n''est pas déductible', '{}'::jsonb, null, 'percent', 10, 'purchase', 'domestic', date '2015-01-01', null, 'Code général des impôts 2016, article 190 a et article 191 : ne sont pas déductibles la TVA des dépenses de logement, hébergement, restauration, réception, spectacles, location de véhicules et transports de personnes, ni celle des véhicules conçus pour le transport de personnes. La taxe suit la charge au compte 8315 et n''atteint aucune case.', null, null, 210, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('DJ', 'DJ-S-10', 'TVA 10 % — taux normal (vente)', '{}'::jsonb, null, 'percent', 10, 'sale', 'domestic', date '2015-01-01', null, 'Code général des impôts 2016, article 187, alinéa 1 : « Le taux normal de 10 % est applicable à toutes les opérations taxables » (le taux de 7 % de la loi n°43/AN/08 a été porté à 10 % par la loi de finances 2015, non lue : le CGI 2016 en porte la mention). Champ : articles 171 à 173 ; base d''imposition : articles 184 à 186 (escomptes, remises et rabais en sont exclus).', null, null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('DJ', 'DJ-S-EXEMPT-AGRI', 'TVA exonérée — produits agricoles non transformés vendus par leurs producteurs (vente)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2015-01-01', null, 'Code général des impôts 2016, article 176, 1 : ventes effectuées directement aux consommateurs par les agriculteurs, éleveurs ou pêcheurs de produits non transformés de leur culture, élevage ou pêche. Le chiffre d''affaires exonéré est déclaré à la ligne 8 de la déclaration et n''ouvre aucun droit à déduction (article 188).', null, null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('DJ', 'DJ-S-EXEMPT-BANK', 'TVA exonérée — opérations bancaires et d''assurance (vente)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2015-01-01', null, 'Code général des impôts 2016, article 176, 2 : opérations bancaires et opérations d''assurance et de réassurance, avec les prestations des courtiers et intermédiaires d''assurances. Le chiffre d''affaires exonéré est déclaré à la ligne 8 de la déclaration et n''ouvre aucun droit à déduction (article 188).', null, null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('DJ', 'DJ-S-EXEMPT-HOUSING', 'TVA exonérée — locations de locaux d''habitation et de terrains ou locaux nus (vente)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2015-01-01', null, 'Code général des impôts 2016, article 176, 6 et 7 : locations de terrains non aménagés et de locaux nus (option possible, article 177) et locations de locaux destinés à l''habitation du locataire. Le chiffre d''affaires exonéré est déclaré à la ligne 8 de la déclaration et n''ouvre aucun droit à déduction (article 188).', null, null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('DJ', 'DJ-S-EXEMPT-NONPROFIT', 'TVA exonérée — organismes sans but lucratif à gestion désintéressée (vente)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2015-01-01', null, 'Code général des impôts 2016, article 176, 4 : services sociaux, sanitaires, éducatifs, sportifs, culturels, philanthropiques ou religieux rendus par des organismes sans but lucratif à gestion bénévole et désintéressée ; taxables lorsqu''ils agissent dans un secteur concurrentiel. Le chiffre d''affaires exonéré est déclaré à la ligne 8 de la déclaration et n''ouvre aucun droit à déduction (article 188).', null, null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('DJ', 'DJ-S-EXEMPT-PRESS', 'TVA exonérée — journaux et périodiques imprimés (vente)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2015-01-01', null, 'Code général des impôts 2016, article 176, 3 : importation et vente de journaux et périodiques, publicité exclue. Le chiffre d''affaires exonéré est déclaré à la ligne 8 de la déclaration et n''ouvre aucun droit à déduction (article 188).', null, null, 80, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('DJ', 'DJ-S-ZERO-EXPORT', 'TVA 0 % — exportations et services liés (vente)', '{}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2015-01-01', null, 'Code général des impôts 2016, article 187, alinéa 2, a et b : taux de 0 % pour les livraisons de biens expédiés hors de Djibouti sous déclaration visée par la douane et pour les services directement liés aux exportations ou au transit (transport, commissionnaires en douane, manutention, gardiennage, magasinage, emballage). Le taux zéro conserve le droit à déduction (article 188).', null, null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('DJ', 'DJ-S-ZERO-TRANSPORT', 'TVA 0 % — transports internationaux et avitaillement (vente)', '{}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2015-01-01', null, 'Code général des impôts 2016, article 187, alinéa 2, c, renvoyant à l''article 180 a : transports internationaux de voyageurs en provenance ou à destination d''un État tiers, agences de voyage qui les concernent, avitaillement des navires et des aéronefs à destination de l''étranger.', null, null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

