    ('DJ-S-EXEMPT-AGRI', 'credit_note', 'base', 100, null, 'EXEMPT', array['EXEMPT']::text[], -100, 'DJ-VAT', 10),
    ('DJ-S-EXEMPT-BANK', 'invoice', 'base', 100, null, 'EXEMPT', array['EXEMPT']::text[], 100, 'DJ-VAT', 10),
