insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('DJ', 'DJ-VAT', 'Déclaration de TVA (mensuelle)', array['month']::declaration_period[], 'month'::declaration_period, date '2015-01-01', null, 'Code général des impôts 2016, article 206 : la TVA est un impôt déclaratif liquidé chaque mois sur une déclaration, selon le modèle fourni par l''administration, indiquant pour le mois précédent le montant des opérations réalisées, des opérations taxables et la TVA déductible ; la déclaration est accompagnée du paiement (« néant » si aucune opération). Le modèle du guide de la TVA (2008, lignes 1 à 22) compte 22 lignes ; le pack reprend les lignes 5, 6, 7, 8, 10, 16, 19 et 20 sous des noms de cases (TAX10, ZERO, EXEMPT, TURNOVER, INPUT, CREDIT, PAYABLE, EXCESS) et ne distingue pas les lignes 2 à 4, 11 à 14 ni 17, 18, 21. Voir README.md.', true,'day_of_month_after_period'::filing_deadline_rule, 20, null, 'Code général des impôts 2016, article 207 : la déclaration est déposée au plus tard le 20 de chaque mois, ou le jour ouvrable suivant si le 20 est férié ; les montants sont arrondis au franc le plus proche.', 'cgi', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

