  ('DJ', 'DJ-VAT', 'INPUT', 'base', 'Achats et charges — montant hors TVA', '{}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts 2016, articles 188 et 189 (lignes 11 à 14 du modèle, non distinguées).', 'cgi'),
  ('DJ', 'DJ-VAT', 'INPUT', 'tax', 'Achats et charges — TVA déductible (lignes 11 à 14)', '{}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts 2016, articles 188 et 189 : déduction le même mois que la réalisation des opérations imposables.', 'cgi'),
