  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'delivery_date',
  tax_point_legal_reference     = 'Code général des impôts 2016, articles 182 et 183 : le fait générateur est la livraison pour les ventes et l''exécution pour les services ; la taxe est exigible à la livraison pour les biens et à l''encaissement du prix ou des acomptes pour les prestations de services (paiement d''après les débits sur autorisation). Le pack retient la date de livraison ; l''exigibilité à l''encaissement des services est un manque, voir README.md.',
  tax_point_source_key          = 'cgi',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = 'Code général des impôts 2016, article 194 : la TVA perçue sur des ventes ou services ensuite résiliés se régularise ; une écriture validée n''est pas effacée mais corrigée par une note de crédit et une contre-écriture.',
