  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Aucune obligation de facturation électronique ni d''échange de factures structurées n''a été trouvée dans le Code général des impôts 2016 (article 208 : mentions de la facture papier). `profile`, `party_scheme` et `vat_scheme` restent vides et `obligation` vaut `none`. Voir README.md.',
  einvoice_source_key           = 'cgi',
